import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { App } from 'aws-cdk-lib';
import { createStack } from './product.mjs';

// Trusted, private native Node preview. It synthesizes the actual product stack
// locally and returns only bounded counts; no CloudFormation template or AWS
// API call leaves this module. The gateway Worker currently cannot execute it.
export async function preview({ configuration, selected_components }) {
  let outdir;
  try {
    if (!Array.isArray(selected_components) || selected_components.length !== 1 || selected_components[0] !== 'stack') {
      return { ok: false, status: 'invalid', slug: 'bedrock-knowledge-base-cdk', selected_components: [], resource_count: 0, diagnostic_codes: ['invalid_selection'] };
    }
    if (!configuration || configuration.language !== 'javascript') {
      return { ok: false, status: 'invalid', slug: 'bedrock-knowledge-base-cdk', selected_components: ['stack'], resource_count: 0, diagnostic_codes: ['configuration_invalid'] };
    }
    outdir = mkdtempSync(join(tmpdir(), 'secondwind-private-cdk-preview-'));
    const app = new App({ outdir, analyticsReporting: false });
    createStack(app, { configuration, selected_components });
    const assembly = app.synth();
    const resource_count = assembly.stacks.reduce((sum, stack) => sum + Object.keys(stack.template?.Resources || {}).length, 0);
    return { ok: true, status: 'complete', slug: 'bedrock-knowledge-base-cdk', selected_components: ['stack'], resource_count };
  } catch {
    return { ok: false, status: 'invalid', slug: 'bedrock-knowledge-base-cdk', selected_components: ['stack'], resource_count: 0, diagnostic_codes: ['validation_failed'] };
  } finally {
    if (outdir) rmSync(outdir, { recursive: true, force: true });
  }
}

import { App, Stack } from 'aws-cdk-lib';
import * as s3 from 'aws-cdk-lib/aws-s3';
import { BedrockFoundationModel, VectorKnowledgeBase } from '@cdklabs/generative-ai-cdk-constructs/lib/cdk-lib/bedrock';

export function createStack(app, { configuration: c }) {
  if (!c || typeof c.knowledge_base_name !== 'string' || typeof c.instruction !== 'string') {
    throw new Error('invalid_configuration');
  }
  const stack = new Stack(app, 'BedrockKnowledgeBaseStack');
  const knowledgeBase = new VectorKnowledgeBase(stack, 'KnowledgeBase', {
    name: c.knowledge_base_name,
    instruction: c.instruction,
    embeddingsModel: BedrockFoundationModel.TITAN_EMBED_TEXT_V2_1024,
  });
  if (c.s3_bucket_arn) {
    knowledgeBase.addS3DataSource({ bucket: s3.Bucket.fromBucketArn(stack, 'SourceBucket', c.s3_bucket_arn) });
  }
  return stack;
}

export function synthesize(configuration) {
  const app = new App({ analyticsReporting: false });
  createStack(app, { configuration });
  return app.synth();
}

